def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_sieve(n):
    primes = [True for i in range(n + 1)]
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i * i, n + 1, i):
                primes[j] = False
    return [i for i, p in enumerate(primes) if p]

print(is_prime(31))
print(is_prime(33))
print(prime_sieve(31))
print(prime_sieve(33))
```

