      return [path]
    for neighbor in graph[vertex]:
      stack.append((neighbor, path + [neighbor]))
  return []

Using DFS with memoization to avoid duplicate paths
def dfs(graph, src, dest):
  memo = {}
  def helper(vertex):
    if (vertex, dest) in memo:
      return memo[(vertex, dest)]
    if vertex == dest:
      return [[vertex]]
    paths = []
    for neighbor in graph[vertex]:
      paths.extend(helper(neighbor))
    memo[(vertex, dest)] = paths
    return paths
  return helper(src)

